import { BrowserRouter, Routes, Route } from 'react-router-dom'
import { Container } from 'react-bootstrap';
import Login from './component/Log'
function App() {
    return (
        <>
            <BrowserRouter>
                <Container>
                    <Routes>
                        <Route path="/" element={<Login />} />
                    </Routes>
                </Container>
            </BrowserRouter >
        </>
    )
}

export default App;
